from typing import List
import heapq

def get_skyline(buildings: List[List[int]]) -> List[List[int]]:
    events = []
    for L, R, H in buildings:
        events.append((L, -H, R))
        events.append((R, 0, 0))
    events.sort()

    result = [(0, 0)]
    heap = [(0, float('inf'))]
    for x, neg_h, r in events:
        while x >= heap[0][1]:
            heapq.heappop(heap)
        if neg_h != 0:
            heapq.heappush(heap, (neg_h, r))
        max_height = -heap[0][0]
        if max_height != result[-1][1]:
            result.append([x, max_height])
    return result[1:]

