from typing import List

def enhanced_interpolation_search(array: List[int], search_key: int) -> int:
    low = 0
    high = len(array) - 1

    while low <= high and search_key >= array[low] and search_key <= array[high]:
        # Avoid division by zero
        if array[high] == array[low]:
            if search_key == array[low]:
                return low
            else:
                return -1

        pos = low + ((search_key - array[low]) * (high - low)) // (array[high] - array[low])

        if array[pos] == search_key:
            return pos
        elif array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

