import heapq

def top_k_accessed_files(files: List[Tuple[int, int]], k: int) -> List[int]:
    if not files or k == 0:
        return []

    # Use a min-heap to keep track of the top k accessed files
    min_heap = []
    for file_id, access_count in files:
        if len(min_heap) < k:
            heapq.heappush(min_heap, (access_count, file_id))
        elif access_count > min_heap[0][0] or (access_count == min_heap[0][0] and file_id < min_heap[0][1]):
            heapq.heappop(min_heap)
            heapq.heappush(min_heap, (access_count, file_id))

    # Extract the file IDs from the heap and sort them by access count and file ID
    result = [file_id for _, file_id in sorted(min_heap, key=lambda x: (-x[0], x[1]))]
    return result

